use strict; use warnings;
my $BIN='/workspace/dataset/test15_executable';
# reference spec
sub ref_underscore {
    my ($in)=@_; my $out='';
    for my $i (0..length($in)-1) {
        my $c = substr($in,$i,1); my $o = ord($c);
        if ($o>=0x41 && $o<=0x5A) { $out .= '_' if $i>0; $out .= chr($o+0x20); }
        else { $out .= $c; }
    }
    return $out;
}
# run binary, return (stdout, stderr, rc)
sub run {
    my @args=@_;
    my $pid = open(my $fh, '-|');
    die "fork" unless defined $pid;
    if ($pid==0) { open(STDERR,'>','/tmp/perr') or die; exec($BIN,@args) or exit 127; }
    local $/; my $out=<$fh>; $out='' unless defined $out; close($fh); my $rc=$?;
    open(my $e,'<','/tmp/perr'); local $/; my $err=<$e>; $err='' unless defined $err; close $e;
    return ($out,$err,$rc);
}
# underscore(W) via `dummy W`: lines 1,2 fixed ("dummys","dummy"); last 3 fixed ("0","1","ummy")
# lines 3..(n-3) = pluralize(W),camelize(W),underscore(W) possibly with embedded newlines.
sub under_line5 {
    my ($w)=@_;
    my ($out,$err,$rc)=run('dummy',$w);
    my @l = split(/\n/, $out, -1);
    pop @l if @l && $l[-1] eq '';
    return ($l[4], $out, $err, $rc, scalar(@l));
}
our @FAIL;
sub chk {
    my ($w,$label)=@_;
    my ($got,$out,$err,$rc,$nl)=under_line5($w);
    my $exp=ref_underscore($w);
    $got='' unless defined $got;
    if ($got ne $exp || $rc!=0 || $err ne '') {
        push @FAIL, [$w,$exp,$got,$rc,$err,$out];
        printf("MISMATCH in=%s\n  exp=%s\n  got=%s\n  rc=%d err=%s nlines=%d\n", hx($w),hx($exp),hx($got),$rc>>8,$err,$nl);
        return 0;
    }
    return 1;
}
sub hx { my $s=shift; my $r=join('',map { my $o=ord($_); ($o>=32&&$o<127&&$_ ne '\\')?$_:sprintf("\\x%02x",$o) } split//,$s); return "[$r]"; }
1;
